import { useEffect, useState } from "react";
import { cn } from "@/lib/utils";
import type { CodeFile } from "./showcase";

interface PropRow {
  name: string;
  type: string;
  required: boolean;
  default: string | null;
  description: string;
}
interface CompProps {
  component: string;
  extends: string[];
  props: PropRow[];
}

// Generated by scripts/props.mjs from each component's TypeScript. One small
// file per component, loaded only when its docs page is open.
const loaders = import.meta.glob<CompProps[]>("./props/*.json", { import: "default" });

function keyFor(files: CodeFile[]) {
  for (const f of files) {
    if (!f.name.startsWith("components/depth/")) continue;
    const key = f.name.replace(/^components\/depth\//, "").replace(/\.tsx$/, "").replace(/\//g, "__");
    if (loaders[`./props/${key}.json`]) return key;
  }
  return null;
}

const code = "rounded bg-depth-elevated px-1.5 py-0.5 font-mono text-[12px] leading-5 break-words";

function TypeCell({ type }: { type: string }) {
  return <code className={cn(code, "text-depth-accent")}>{type}</code>;
}
function DefaultCell({ value }: { value: string | null }) {
  return value ? <code className={code}>{value}</code> : <span className="text-depth-muted">-</span>;
}

function Table({ data }: { data: CompProps }) {
  return (
    <div className="mt-4 first:mt-0">
      <h4 className="font-mono text-sm font-medium">&lt;{data.component} /&gt;</h4>
      {data.extends.length > 0 && (
        <p className="mt-1 text-xs text-depth-muted">
          Also accepts every prop of <code className="font-mono">{data.extends.join(", ")}</code>.
        </p>
      )}
      {/* Wide screens: a real table. */}
      <div className="mt-3 hidden overflow-x-auto rounded-xl border border-depth-border sm:block">
        <table className="w-full min-w-[620px] border-collapse text-left text-sm">
          <thead>
            <tr className="border-b border-depth-border bg-depth-elevated/60 text-xs uppercase tracking-wider text-depth-muted">
              <th scope="col" className="px-4 py-2.5 font-medium">Prop</th>
              <th scope="col" className="px-4 py-2.5 font-medium">Type</th>
              <th scope="col" className="px-4 py-2.5 font-medium">Default</th>
              <th scope="col" className="px-4 py-2.5 font-medium">Description</th>
            </tr>
          </thead>
          <tbody>
            {data.props.map((p) => (
              <tr key={p.name} className="border-b border-depth-border/70 align-top last:border-0">
                <th scope="row" className="whitespace-nowrap px-4 py-3 font-mono text-[13px] font-medium">
                  {p.name}
                  {p.required && <span className="ml-1 text-red-500" title="Required" aria-label="required">*</span>}
                </th>
                <td className="max-w-[280px] px-4 py-3"><TypeCell type={p.type} /></td>
                <td className="px-4 py-3"><DefaultCell value={p.default} /></td>
                <td className="px-4 py-3 text-depth-muted">{p.description}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {/* Phones: one card per prop, so nothing needs sideways scrolling. */}
      <ul className="mt-3 space-y-2 sm:hidden">
        {data.props.map((p) => (
          <li key={p.name} className="rounded-xl border border-depth-border bg-depth-surface/60 p-3">
            <div className="flex flex-wrap items-center gap-2">
              <span className="font-mono text-[13px] font-medium">{p.name}</span>
              {p.required && <span className="rounded bg-red-500/10 px-1.5 text-[11px] font-medium text-red-500">required</span>}
            </div>
            <p className="mt-1 text-sm text-depth-muted">{p.description}</p>
            <dl className="mt-2 grid grid-cols-[auto_1fr] items-baseline gap-x-3 gap-y-1.5 text-xs">
              <dt className="text-depth-muted">Type</dt>
              <dd className="min-w-0"><TypeCell type={p.type} /></dd>
              <dt className="text-depth-muted">Default</dt>
              <dd className="min-w-0"><DefaultCell value={p.default} /></dd>
            </dl>
          </li>
        ))}
      </ul>
    </div>
  );
}

/** "Props" reference shown under a component's demo, like other component docs sites. */
export function PropsTable({ files }: { files: CodeFile[] }) {
  const key = keyFor(files);
  const [data, setData] = useState<CompProps[] | null>(null);

  useEffect(() => {
    let live = true;
    setData(null);
    if (key) loaders[`./props/${key}.json`]().then((d) => live && setData(d));
    return () => { live = false; };
  }, [key]);

  if (!key || !data || data.length === 0) return null;
  return (
    <div className="mt-10">
      <h3 className="text-lg font-semibold tracking-tight">Props</h3>
      <p className="mt-1 text-sm text-depth-muted">
        Every prop the component accepts. <span className="text-red-500">*</span> marks a required prop. Leave the rest out to use the default.
      </p>
      <div className="mt-4">
        {data.map((d) => <Table key={d.component} data={d} />)}
      </div>
    </div>
  );
}
